-- ISS-11212 (PLN-2122 Step 2): GitHub comment sync schema. Generated by
-- `prisma migrate dev --create-only`, then hand-edited:
--   1. The `(pr_state, comments_reconciled_at)` index moved to its own
--      migration (20261001185259) so it builds CONCURRENTLY on a populated
--      table.
--   2. HAND-WRITTEN: the anchor function, the anchor data step for existing
--      GITHUB threads, and a bridge trigger for threads written after it.
-- `REVIEW_SUMMARY` is added but not used here; no old api bundle writes it.

-- AlterEnum
ALTER TYPE "GitHubCommentThreadKind" ADD VALUE 'REVIEW_SUMMARY';

-- AlterTable
ALTER TABLE "github_comment_thread_projections" ADD COLUMN     "original_line" INTEGER;

-- AlterTable
ALTER TABLE "pull_request_detail" ADD COLUMN     "comments_reconcile_claimed_at" TIMESTAMP(3),
ADD COLUMN     "comments_reconciled_at" TIMESTAMP(3);

-- HAND-WRITTEN: the `{ v: 1, ...CommentAnchor }` envelope
-- (packages/api/src/types/comment-anchor.ts) for one GitHub thread projection.
-- `code` when the projection has a path, else `artifact` (PLN-2122 decision 7).
-- NULL when a field the code anchor requires has no valid source value: no
-- repository, a commit sha the schema rejects, no side, or a range the schema
-- rejects. Also NULL for a backfill row with a `line` and no `original_line`:
-- the backfill wrote `original_line` into `line` for an outdated comment until
-- ISS-11212 stopped `mapPullRequestReviewComment` folding it, so that `line`
-- may not be GitHub's. Such a thread keeps an absent anchor rather than a
-- made-up one.
-- ISS-11212 github anchor function begin
CREATE FUNCTION "iss11212_github_thread_anchor"(
  p "github_comment_thread_projections",
  repository text
) RETURNS jsonb
LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE
    WHEN p."path" IS NULL THEN jsonb_build_object('v', 1, 'kind', 'artifact')
    WHEN repository IS NULL
      OR length(repository) NOT BETWEEN 1 AND 500
      OR p."commit_sha" IS NULL
      OR p."commit_sha" !~ '^[0-9a-f]{40}([0-9a-f]{24})?$'
      OR length(p."path") NOT BETWEEN 1 AND 4096
      OR p."side" IS NULL
      OR p."line" < 1
      OR p."start_line" < 1
      OR p."original_line" < 1
      OR (
        p."fetch_mechanism" = 'backfill'
        AND p."line" IS NOT NULL
        AND p."original_line" IS NULL
      )
      OR (
        p."start_line" > p."line"
        AND (p."start_side" IS NULL OR p."start_side" = p."side")
      )
      THEN NULL
    ELSE jsonb_build_object(
        'v', 1,
        'kind', 'code',
        'repository', repository,
        'commitSha', p."commit_sha",
        'path', p."path",
        'side', lower(p."side"::text),
        'endLine', p."line"
      )
      || CASE
        WHEN p."start_line" IS NULL THEN '{}'::jsonb
        WHEN p."start_side" IS NULL THEN jsonb_build_object('startLine', p."start_line")
        ELSE jsonb_build_object(
          'startLine', p."start_line",
          'startSide', lower(p."start_side"::text)
        )
      END
      || CASE
        WHEN p."original_line" IS NULL THEN '{}'::jsonb
        ELSE jsonb_build_object('originalEndLine', p."original_line")
      END
  END
$$;
-- ISS-11212 github anchor function end

-- ISS-11212 github anchor data step begin
-- HAND-WRITTEN: anchor every existing GITHUB thread that has none yet.
-- OUTDATED when GitHub no longer places a code comment on a line.
UPDATE "comment_threads" AS t
SET "anchor" = a."anchor",
    "anchor_state" = CASE
      WHEN p."path" IS NOT NULL AND p."line" IS NULL THEN 'OUTDATED'
      ELSE 'ANCHORED'
    END::"CommentAnchorState"
FROM "github_comment_thread_projections" AS p
JOIN "pull_request_detail" AS pr ON pr."id" = p."pull_request_detail_id"
CROSS JOIN LATERAL (
  SELECT "iss11212_github_thread_anchor"(p, pr."repository_full_name") AS "anchor"
) AS a
WHERE t."id" = p."thread_id"
  AND t."source" = 'GITHUB'
  AND t."anchor" IS NULL
  AND a."anchor" IS NOT NULL;
-- ISS-11212 github anchor data step end

-- HAND-WRITTEN bridge: in production this migration runs in the new api
-- build's prebuild while the previous bundle still serves
-- (docs/runbooks/deploy-paths.md), and no bundle writes GitHub anchors until
-- PLN-2122 Step 3. This trigger applies the data step to each projection row
-- written after it. It fills an absent anchor, and replaces a stored one only
-- while that anchor still equals what the row's previous values derive, so a
-- thread the provider moves or outdates keeps following its projection but an
-- anchor the comment service wrote is never overwritten. Drop the trigger and
-- both functions with the other ISS-11212 bridges once no api bundle older
-- than PLN-2122 Step 3 can serve (ISS-11212, PLN-2120 Step 6 cleanup
-- migration).
-- ISS-11212 github anchor bridge begin
CREATE FUNCTION "iss11212_github_thread_anchor_bridge"() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  repository text;
  next_anchor jsonb;
  next_state "CommentAnchorState";
  previous_anchor jsonb;
  previous_state "CommentAnchorState";
BEGIN
  SELECT pr."repository_full_name" INTO repository
  FROM "pull_request_detail" AS pr
  WHERE pr."id" = NEW."pull_request_detail_id";
  next_anchor := "iss11212_github_thread_anchor"(NEW, repository);
  next_state := CASE
    WHEN next_anchor IS NULL THEN NULL
    WHEN NEW."path" IS NOT NULL AND NEW."line" IS NULL THEN 'OUTDATED'
    ELSE 'ANCHORED'
  END;
  IF TG_OP = 'UPDATE' THEN
    previous_anchor := "iss11212_github_thread_anchor"(OLD, repository);
    previous_state := CASE
      WHEN OLD."path" IS NOT NULL AND OLD."line" IS NULL THEN 'OUTDATED'
      ELSE 'ANCHORED'
    END;
  END IF;

  UPDATE "comment_threads" AS t
  SET "anchor" = next_anchor,
      "anchor_state" = next_state
  WHERE t."id" = NEW."thread_id"
    AND t."source" = 'GITHUB'
    AND (
      (t."anchor" IS NULL AND next_anchor IS NOT NULL)
      OR (
        t."anchor" = previous_anchor
        AND t."anchor_state" = previous_state
        AND (t."anchor", t."anchor_state") IS DISTINCT FROM (next_anchor, next_state)
      )
    );
  RETURN NULL;
END $$;

CREATE TRIGGER "github_comment_thread_projections_iss11212_anchor_bridge"
AFTER INSERT OR UPDATE OF "thread_kind", "path", "line", "original_line", "side", "start_line", "start_side", "commit_sha", "fetch_mechanism"
ON "github_comment_thread_projections"
FOR EACH ROW
EXECUTE FUNCTION "iss11212_github_thread_anchor_bridge"();
-- ISS-11212 github anchor bridge end
